bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env;
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const q=await db.query("SELECT l.buyer_user_id,l.seller_user_id,l.delivery_key,l.kind FROM videobot_stars_ledger l WHERE l.listing_id=(SELECT listing_id FROM videobot_post_receipts WHERE paid_message_id=$1)",[4691]);
 if(q.rowCount<1)process.exitCode=61;
 else{
  const paid=q.rows.filter(x=>x.kind==='paid');
  const refunds=q.rows.filter(x=>x.kind==='refunded');
  const buyers=[...new Set(paid.map(x=>String(x.buyer_user_id)))];
  if(buyers.length>1)process.exitCode=71;
  else if(buyers.length===1 && buyers[0]===String(paid[0].seller_user_id))process.exitCode=72;
  else if(buyers.length===1 && buyers[0]==='788044853')process.exitCode=73;
  else if(buyers.length===1)process.exitCode=74;
  else process.exitCode=75;
 }
}catch(e){console.error('TEST_BUYER_DIAG_SQL_CODE='+String(e.code??'OTHER').slice(0,8));process.exitCode=79}
finally{await db.end()}
JS
